#!/usr/bin/env python3
"""
Round 140b (culprits-tiles-more), 2 October 2026.

sea_around_us.py (new): Sea Around Us catch by fishing country.
gfw_trawling.py (new): Global Fishing Watch fishing hours by gear (needs GFW_TOKEN).
cultivated_meat.py (new): meat grown from cells, US states, with additions.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/sea_around_us.py': '', 'scripts/gfw_trawling.py': '', 'scripts/cultivated_meat.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round140b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round140b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
